class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Create a list to hold each diagonal
        diagonals = [[] for _ in range(2 * n - 1)]

        # Fill the diagonals
        for i in range(n):
            for j in range(n):
                # The diagonal index is i - j
                diag_index = i - j
                diagonals[diag_index].append(grid[i][j])

        # Sort the bottom-left triangle (non-increasing)
        for i in range(n):
            for j in range(n):
                if i - j >= 0:
                    # Extract the diagonal
                    diag_index = i - j
                    # Sort in non-increasing order
                    diagonals[diag_index].sort(reverse=True)

        # Sort the top-right triangle (non-decreasing)
        for i in range(n):
            for j in range(n):
                if i - j < 0:
                    diag_index = i - j
                    # Sort in non-decreasing order
                    diagonals[diag_index].sort()

        # Reconstruct the matrix
        result = [[0 for _ in range(n)] for _ in range(n)]
        index = 0
        for i in range(n):
            for j in range(n):
                diag_index = i - j
                result[i][j] = diagonals[diag_index][index]
                index += 1

        return result

