    def longestPalindrome(self, s: str, t: str) -> int:
        # Helper function to check if a string is a palindrome
        def is_palindrome(string):
            return string == string[::-1]

        max_len = 0

        # Try all possible substrings from s and t
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                for k in range(len(t)):
                    for l in range(k + 1, len(t) + 1):
                        combined = s[i:j] + t[k:l]
                        if is_palindrome(combined):
                            max_len = max(max_len, len(combined))

        # Also check the individual maximum palindrome in s and t
        max_s = max(len(x) for x in [s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1) if is_palindrome(s[i:j])])
        max_t = max(len(x) for x in [t[i:j] for i in range(len(t)) for j in range(i + 1, len(t) + 1) if is_palindrome(t[i:j])])

        return max(max_len, max_s, max_t)

