        if len(nums) < 2:
            return 0

        # Precompute the maximum length of increasing subarrays starting at each index
        n = len(nums)
        increasing = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] < nums[i + 1]:
                increasing[i] = increasing[i + 1] + 1
            else:
                increasing[i] = 1

        # Now find the maximum k such that there exist two adjacent subarrays of length k
        max_k = 0
        for i in range(n - 2):
            if increasing[i] >= 2 and increasing[i + 1] >= 2:
                current_k = min(increasing[i], increasing[i + 1])
                if current_k > max_k:
                    max_k = current_k

        return max_k

