from typing import List
import heapq

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Initialize the graph with the original edges (i -> i+1)
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        def dijkstra(start, end):
            dist = [float('inf')] * n
            dist[start] = 0
            heap = [(0, start)]
            while heap:
                d, u = heapq.heappop(heap)
                if u == end:
                    return d
                if d > dist[u]:
                    continue
                for v in graph[u]:
                    if dist[v] > d + 1:
                        dist[v] = d + 1
                        heapq.heappush(heap, (dist[v], v))
            return dist[end]

        result = []
        for query in queries:
            u, v = query
            graph[u].append(v)
            shortest = dijkstra(0, n - 1)
            result.append(shortest)

        return result

def run_check_correct():
    sol = Solution()
    print(sol.shortestDistanceAfterQueries(5, [[2,4],[0,2],[0,4]]))  # Output: [3, 2, 1]
    print(sol.shortestDistanceAfterQueries(4, [[0,3],[0,2]]))       # Output: [1, 1]

