class Solution:
    def maxFrequency(self, nums: List[int], k: int, numOperations: int) -> int:
        # Sort the array to help with greedy approach
        nums.sort()
        n = len(nums)

        # We use a sliding window to find the maximum number of elements that can be adjusted
        left = 0
        max_freq = 0

        for right in range(n):
            # We want to make sure that the total adjustment is within k * numOperations
            while right - left + 1 > max_freq:
                current_total = nums[right] * (right - left + 1) - sum(nums[left:right+1])
                if current_total <= k * numOperations:
                    max_freq = right - left + 1
                else:
                    left += 1

        return max_freq

