    def countOfPairs(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i][j] represents the number of ways to form the first i elements with arr1[i-1] = j
        dp = [[0] * (max(nums) + 1) for _ in range(n)]

        # Base case: for i=0, arr1[0] can be anything <= nums[0], arr2[0] is nums[0] - arr1[0]
        for j in range(0, nums[0] + 1):
            dp[0][j] = 1

        for i in range(1, n):
            for j in range(0, nums[i] + 1):
                # For each possible value of arr1[i], sum up all valid transitions from i-1
                for k in range(0, j + 1):
                    if nums[i] - j >= nums[i-1] - k:
                        dp[i][j] += dp[i-1][k]
                        dp[i][j] %= MOD

        # Sum all possible values for the last element
        total = 0
        for j in range(0, nums[-1] + 1):
            total += dp[n-1][j]
            total %= MOD

        return total

