class Solution:
    def countGoodNodes(self, edges: List[List[int]]) -> int:
        # Build adjacency list
        n = len(edges) + 1
        tree = [[] for _ in range(n)]
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        # To store the sizes of subtrees
        subtree_sizes = [0] * n

        # Post-order DFS to calculate subtree sizes
        def dfs(node, parent):
            size = 1
            children_sizes = []
            for neighbor in tree[node]:
                if neighbor != parent:
                    children_sizes.append(dfs(neighbor, node))
            # Check if all children have the same size
            if len(children_sizes) == 0:
                subtree_sizes[node] = 1
                return 1
            elif len(set(children_sizes)) == 1:
                subtree_sizes[node] = 1 + sum(children_sizes)
                return 1 + sum(children_sizes)
            else:
                subtree_sizes[node] = 1 + sum(children_sizes)
                return subtree_sizes[node]

        # Start DFS from root (0)
        dfs(0, -1)

        # Count the number of good nodes
        good_nodes = 0
        def count_good(node, parent):
            nonlocal good_nodes
            if len(tree[node]) == 0:
                good_nodes += 1
                return 1
            # Check if all children have the same size
            children_sizes = []
            for neighbor in tree[node]:
                if neighbor != parent:
                    children_sizes.append(subtree_sizes[neighbor])
            if len(set(children_sizes)) == 1:
                good_nodes += 1
            return subtree_sizes[node]

        count_good(0, -1)
        return good_nodes

