class Solution:
    def isPossibleToRearrange(self, s: str, t: str, k: int) -> bool:
        # Check if the lengths are compatible
        if len(s) % k != 0:
            return False

        # Count character frequencies in s and t
        s_count = Counter(s)
        t_count = Counter(t)

        # Check if each character in t is present in s
        for char in t_count:
            if char not in s_count:
                return False

        # Check if each character in t has a frequency that is a multiple of the same in s
        for char in t_count:
            if t_count[char] % s_count[char] != 0:
                return False

        return True

def evaluate_solution():
    sol = Solution()
    print(sol.isPossibleToRearrange("abcd", "cdab", 2))  # True
    print(sol.isPossibleToRearrange("aabbcc", "bbaacc", 3))  # True
    print(sol.isPossibleToRearrange("aabbcc", "bbaacc", 2))  # False

