from typing import List
import heapq

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n = len(moveTime)
        m = len(moveTime[0])

        # Directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Dijkstra's priority queue: (time, row, col)
        heap = [(max(moveTime[0][0], 0), 0, 0)]

        # Visited matrix to track the minimum time to reach each cell
        visited = [[float('inf')] * m for _ in range(n)]
        visited[0][0] = max(moveTime[0][0], 0)

        while heap:
            time, row, col = heapq.heappop(heap)

            if row == n - 1 and col == m - 1:
                return time

            if time > visited[row][col]:
                continue

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < n and 0 <= new_col < m:
                    new_time = max(time + 1, moveTime[new_row][new_col])
                    if new_time < visited[new_row][new_col]:
                        visited[new_row][new_col] = new_time
                        heapq.heappush(heap, (new_time, new_row, new_col))

        return -1  # If not reachable (shouldn't happen per problem constraints)

