class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7
        n = len(num)
        from collections import Counter

        # Store the count of each digit
        digit_counts = Counter(num)

        # We'll use memoization to avoid recomputing
        memo = {}

        def dp(pos, even_sum, odd_sum, used):
            if pos == n:
                return 1 if even_sum == odd_sum else 0
            key = (pos, even_sum, odd_sum, tuple(sorted(used)))
            if key in memo:
                return memo[key]

            total = 0
            for digit in digit_counts:
                if digit_counts[digit] == 0:
                    continue
                if used[digit] < digit_counts[digit]:
                    if pos % 2 == 0:
                        new_even_sum = even_sum + int(digit)
                        new_used = used.copy()
                        new_used[digit] += 1
                        total += dp(pos + 1, new_even_sum, odd_sum, new_used)
                    else:
                        new_odd_sum = odd_sum + int(digit)
                        new_used = used.copy()
                        new_used[digit] += 1
                        total += dp(pos + 1, even_sum, new_odd_sum, new_used)
                    total %= MOD
            memo[key] = total
            return total

        # Initialize used as a dictionary with all digits as 0
        used = {str(d): 0 for d in range(10)}
        for d in num:
            used[str(d)] += 1

        # Start the DP process
        result = dp(0, 0, 0, used)
        return result % MOD

