        n = len(properties)

        # Function to compute the number of common elements between two properties lists
        def intersect(a: List[int], b: List[int]) -> int:
            return len(set(a) & set(b))

        # Create adjacency matrix
        adj = [[False] * n for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                if intersect(properties[i], properties[j]) >= k:
                    adj[i][j] = True
                    adj[j][i] = True

        # DSU (Union-Find) implementation
        parent = list(range(n))

        def find(u):
            if parent[u] != u:
                parent[u] = find(parent[u])
            return parent[u]

        def union(u, v):
            pu = find(u)
            pv = find(v)
            if pu != pv:
                parent[pu] = pv

        # Build the DSU structure by connecting nodes
        for i in range(n):
            for j in range(i + 1, n):
                if adj[i][j]:
                    union(i, j)

        # Count the number of unique roots (connected components)
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)

