        memo2 = [[-1 for _ in range(n)] for _ in range(n)]  # Child starting from (0, n-1)
        memo3 = [[-1 for _ in range(n)] for _ in range(n)]  # Child starting from (n-1, 0)

        # Helper function for child starting from (i, j)
        def dp(child_start, i, j):
            if i == n - 1 and j == n - 1:
                return fruits[i][j]
            if memo[child_start][i][j] != -1:
                return memo[child_start][i][j]
            max_fruits = 0
            if child_start == 0:
                # Child from (0,0) can move to (i+1,j), (i+1,j+1), (i,j+1)
                if i + 1 < n and j < n:
                    max_fruits = max(max_fruits, dp(0, i+1, j) + fruits[i+1][j])
                if i + 1 < n and j + 1 < n:
                    max_fruits = max(max_fruits, dp(0, i+1, j+1) + fruits[i+1][j+1])
                if i < n and j + 1 < n:
                    max_fruits = max(max_fruits, dp(0, i, j+1) + fruits[i][j+1])
            elif child_start == 1:
                # Child from (0,n-1) can move to (i+1,j-1), (i+1,j), (i+1,j+1)
                if i + 1 < n and j - 1 >= 0:
                    max_fruits = max(max_fruits, dp(1, i+1, j-1) + fruits[i+1][j-1])
                if i + 1 < n and j < n:
                    max_fruits = max(max_fruits, dp(1, i+1, j) + fruits[i+1][j])
                if i + 1 < n and j + 1 < n:
                    max_fruits = max(max_fruits, dp(1, i+1, j+1) + fruits[i+1][j+1])
            elif child_start == 2:
                # Child from (n-1,0) can move to (i-1,j+1), (i,j+1), (i+1,j+1)
                if i - 1 >= 0 and j + 1 < n:
