        # Precompute cost of converting one character to another
        def cost(a, b):
            return min(abs(ord(a) - ord(b)), 26 - abs(ord(a) - ord(b)))

        # Dynamic programming approach for longest palindromic subsequence
        # We use DP[i][j][c] to store the maximum length of a palindrome
        # from i to j using at most c operations
        n = len(s)
        # dp[i][j][c] = max length of palindrome in s[i..j] with c operations
        # We will use a 2D array for each possible cost
        # Since k is up to 200, and n is up to 200, this is feasible
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        # Base case: single character is a palindrome of length 1
        for i in range(n):
            for c in range(k + 1):
                dp[i][i][c] = 1

        # Fill the DP table
        for length in range(2, n + 1):  # length of substring
            for i in range(n - length + 1):
                j = i + length - 1
                for cost_used in range(k + 1):
                    if i == j:
                        dp[i][j][cost_used] = 1
                    else:
                        # Check if we can take s[i] and s[j] as matching characters
                        max_len = 0
                        for c in range(26):
                            original_char = chr(ord('a') + c)
                            if cost(s[i], original_char) <= cost_used:
                                if dp[i + 1][j - 1][cost_used - cost(s[i], original_char)] + 2 > max_len:
                                    max_len = dp[i + 1][j - 1][cost_used - cost(s[i], original_char)] + 2
                        dp[i][j][cost_used] = max_len

        # The answer is the maximum length of a palindrome in the entire string with at most k operations
        result = 0
        for c in range(k + 1):
            result = max(result, dp[0][n - 1][c])
        return result

