class Solution:
    def maxSizedArray(self, s: int) -> int:
        # Function to compute the sum of the array for a given n
        def compute_sum(n):
            if n == 0:
                return 0
            total = 0
            # For each i from 0 to n-1
            for i in range(n):
                # For each j from 0 to n-1
                for j in range(n):
                    # For each k from 0 to n-1
                    for k in range(n):
                        # A[i][j][k] = i * (j OR k)
                        total += i * ((j | k))
            return total

        # Binary search to find the maximum n such that compute_sum(n) <= s
        left = 0
        right = 10**6  # A safe upper bound since the sum grows exponentially
        answer = 0

        while left <= right:
            mid = (left + right) // 2
            current_sum = compute_sum(mid)
            if current_sum <= s:
                answer = mid
                left = mid + 1
            else:
                right = mid - 1

        return answer

