class Solution:
    def countSubmatrices(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        count = 0

        # For each row, create a prefix max matrix
        prefix_max = [[0 for _ in range(n)] for _ in range(m)]

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    prefix_max[i][j] = grid[i][j]
                elif i == 0:
                    prefix_max[i][j] = max(prefix_max[i][j - 1], grid[i][j])
                elif j == 0:
                    prefix_max[i][j] = max(prefix_max[i - 1][j], grid[i][j])
                else:
                    prefix_max[i][j] = max(prefix_max[i - 1][j], prefix_max[i][j - 1], grid[i][j])

        # Count submatrices
        for i in range(m):
            for j in range(n):
                if prefix_max[i][j] <= k:
                    count += 1
        return count

