    coins.sort()
    res = 0
    windowSum = 0
    j = 0
    for li, ri, ci in coins:  # Consider the number line [li..li + k).
      rightBoundary = li + k

      # [lj, rj] is fully in [li..li + k).
      while j + 1 < len(coins) and coins[j + 1][0] < rightBoundary:
