      if j < len(coins) and coins[j][0] < rightBoundary:
        lj, rj, cj = coins[j]
        last = (min(rightBoundary - 1, rj) - lj + 1) * cj

      res = max(res, windowSum + last)
      windowSum -= (ri - li + 1) * ci
    return res

