    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Create a dictionary to map element values to their indices
        element_indices = {}
        for idx, val in enumerate(elements):
            if val not in element_indices:
                element_indices[val] = []
            element_indices[val].append(idx)

        # Sort the groups for processing
        sorted_groups = sorted(enumerate(groups), key=lambda x: x[1])

        # Prepare the result
        result = [-1] * len(groups)

        # For each group, try to assign the smallest index of an element that divides the group size
        for group_idx, group_size in sorted_groups:
