                if group_size % val == 0:
                    # Get the smallest index for this value
                    smallest_idx = element_indices[val][0]
                    result[group_idx] = smallest_idx
                    # Remove this index to avoid reusing it (but note that the problem allows reusing elements)
                    # However, since the problem allows multiple assignments, we can keep all indices
                    break

        return result

