    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        # Sort the worker times to optimize the distribution
        workerTimes.sort()

        # Binary search over possible time values
        left = 0
        right = mountainHeight * max(workerTimes)  # Upper bound for binary search

        def total_reduction(time: int) -> int:
            # For each worker, calculate how much height they can reduce within 'time'
            reduction = 0
            for t in workerTimes:
                x = time // t
                if x > 0:
                    reduction += t * (x * (x + 1)) // 2  # Sum of arithmetic series: t + 2t + ... + xt
