class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        # Kadane's algorithm to find max subarray sum
        def kadane(arr: List[int]) -> int:
            max_current = max_global = arr[0]
            for num in arr[1:]:
                max_current = max(num, max_current + num)
                max_global = max(max_global, max_current)
            return max_global

        if not nums:
            return 0

        # Original array's max subarray sum
        original_max = kadane(nums)

        # If all elements are positive, we can do better by not removing anything
        if all(x > 0 for x in nums):
            return sum(nums)

        # Try removing each unique number once and compute max subarray sum
        unique_numbers = set(nums)
        max_after_removal = original_max

        for x in unique_numbers:
            new_nums = [num for num in nums if num != x]
            if new_nums:
                current_max = kadane(new_nums)
                max_after_removal = max(max_after_removal, current_max)

        return max_after_removal

