class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        # dp[i] represents the minimum cost to remove elements from index i to the end
        dp = [0] * (n + 1)

        # Base case: no elements left, cost is 0
        dp[n] = 0

        # Fill dp from the end to the start
        for i in range(n - 1, -1, -1):
            # If fewer than 3 elements left, remove them all
            if i + 1 <= 3:
                dp[i] = max(nums[i], nums[i + 1]) if i + 1 < n else 0
                if i + 2 < n:
                    dp[i] = min(dp[i], max(nums[i], nums[i + 1]) + dp[i + 2])
                if i + 2 < n and i + 1 < n:
                    dp[i] = min(dp[i], max(nums[i], nums[i + 2]) + dp[i + 1])
            else:
                # Consider all possible pairs in the first three elements
                if i + 1 < n:
                    dp[i] = max(nums[i], nums[i + 1]) + dp[i + 2]
                if i + 2 < n:
                    dp[i] = min(dp[i], max(nums[i], nums[i + 2]) + dp[i + 1])
                if i + 1 < n and i + 2 < n:
                    dp[i] = min(dp[i], max(nums[i + 1], nums[i + 2]) + dp[i + 3])
        return dp[0]

