class Solution:
    def sumOfGoodSubsequences(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        # Use a dictionary to keep track of dp[x] and the number of subsequences ending at x
        dp = {}  # maps value to (sum, count)

        for num in nums:
            # Initialize new entries for this num
            if num not in dp:
                dp[num] = (num, 1)
            else:
                # If already exists, just add to the sum and count
                prev_sum, prev_count = dp[num]
                dp[num] = (prev_sum + num, prev_count + 1)

            # Check for num-1 and num+1
            if num - 1 in dp:
                prev_sum, prev_count = dp[num - 1]
                # Add new subsequences that end with num-1 and now extend to num
                new_sum = prev_sum + num
                new_count = prev_count
                # Update dp[num] if it's better or add to existing
                if num in dp:
                    dp[num] = (dp[num][0] + new_sum, dp[num][1] + new_count)
                else:
                    dp[num] = (new_sum, new_count)

            if num + 1 in dp:
                prev_sum, prev_count = dp[num + 1]
                new_sum = prev_sum + num
                new_count = prev_count
                if num in dp:
                    dp[num] = (dp[num][0] + new_sum, dp[num][1] + new_count)
                else:
                    dp[num] = (new_sum, new_count)

        total_sum = 0
        for key in dp:
            total_sum += dp[key][0]

        return total_sum % MOD

