class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        if n == 0:
            return 0

        # dp[i][v] = number of ways to form the first i elements with arr1[i] = v
        # Initialize DP table
        dp = [{} for _ in range(n)]

        # Base case: first element
        for v in range(0, nums[0] + 1):
            dp[0][v] = 1

        for i in range(1, n):
            for v1 in dp[i - 1]:
                v2 = nums[i] - v1
                if v2 >= 0 and v2 <= nums[i]:
                    # To maintain monotonicity, arr1 must be non-decreasing and arr2 must be non-increasing
                    # So we can only add to dp[i][v1] if v1 is >= the previous arr1 and v2 is <= the previous arr2
                    # Since we are building up, we are only considering current v1 and v2
                    if v1 in dp[i]:
                        dp[i][v1] = (dp[i][v1] + dp[i - 1][v1]) % MOD
                    else:
                        dp[i][v1] = dp[i - 1][v1] % MOD

        # Sum all values in the last dp state
        total = 0
        for v in dp[-1]:
            total = (total + dp[-1][v]) % MOD

        return total

