    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        # dp[i][j][k] = max coins at (i,j) with k neutralizations used
        dp = [[[float('-inf') for _ in range(3)] for _ in range(n)] for _ in range(m)]

        # Initialize the starting cell (0,0)
        dp[0][0][0] = coins[0][0]
        if coins[0][0] < 0:
            dp[0][0][1] = 0  # if we neutralize it, we can get 0
            dp[0][0][2] = 0  # if we neutralize it twice, we can get 0

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                for k in range(3):
                    if i > 0:
                        if dp[i-1][j][k] != float('-inf'):
                            if coins[i][j] >= 0:
                                dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + coins[i][j])
                            else:
                                if k < 2:
                                    dp[i][j][k + 1] = max(dp[i][j][k + 1], dp[i-1][j][k])
                    if j > 0:
                        if dp[i][j-1][k] != float('-inf'):
                            if coins[i][j] >= 0:
