                            else:
                                if k < 2:
                                    dp[i][j][k + 1] = max(dp[i][j][k + 1], dp[i][j-1][k])

        result = float('-inf')
        for k in range(3):
            result = max(result, dp[m-1][n-1][k])
        return result

