class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        len_s = len(s)
        len_p = len(pattern)

        # If pattern is longer than s, it's not possible
        if len_p > len_s:
            return -1

        # Iterate over all possible starting indices in s
        for i in range(len_s - len_p + 1):
            # Extract substring of length len_p starting at i
            substring = s[i:i + len_p]
            mismatch_count = 0
            for j in range(len_p):
                if substring[j] != pattern[j]:
                    mismatch_count += 1
                    if mismatch_count > 1:
                        break
            if mismatch_count <= 1:
                return i

        return -1

