    def makeStringGood(self, s: str) -> int:
        # Count the frequency of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Get the unique frequencies
        unique_freqs = list(freq.values())

        # If all frequencies are the same, no operations needed
        if len(set(unique_freqs)) == 1:
            return 0

        # We can choose any frequency as the target (we'll pick the most frequent one)
        target_freq = max(unique_freqs)

        # Calculate the number of operations needed to make all frequencies equal to target_freq
        operations = 0
        for count in unique_freqs:
            if count < target_freq:
                operations += (target_freq - count)

        return operations

