class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # If k is 1, the entire array is valid and we just return the sum
        if k == 1:
            return sum(nums)

        # We use a dictionary to store the prefix sums at positions that are congruent mod k
        mod_dict = {}
        prefix_sum = 0
        max_sum = float('-inf')

        for i in range(len(nums)):
            prefix_sum += nums[i]
            mod = i % k
            # If the current index is a multiple of k, we check the max sum
            if i % k == 0:
                max_sum = max(max_sum, prefix_sum)
            # If the mod is in the dictionary, we can compute a subarray sum
            if mod in mod_dict:
                current_max = prefix_sum - mod_dict[mod]
                max_sum = max(max_sum, current_max)
            else:
                mod_dict[mod] = prefix_sum

        return max_sum if max_sum != float('-inf') else 0

def evaluate_answer():
