    print(sol.maxSubarraySum([1,2], 1))  # 3
    print(sol.maxSubarraySum([-1,-2,-3,-4,-5], 4))  # -10
    print(sol.maxSubarraySum([-5,1,2,-3,4], 2))  # 4

