class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Initialize a dictionary to store the maximum prefix sum for each remainder mod k
        # Also, track the maximum sum found so far
        prefix_sums = {}
        max_sum = float('-inf')
        current_sum = 0

        for i in range(len(nums)):
            current_sum += nums[i]
            remainder = i % k
            if remainder not in prefix_sums:
                prefix_sums[remainder] = current_sum
            else:
                # We want the minimum prefix sum for each remainder to get the maximum subarray sum
                # For a subarray of length divisible by k, the current prefix sum minus the smallest prefix sum of the same remainder will be the max subarray sum
                prefix_sums[remainder] = min(prefix_sums[remainder], current_sum)
            # Update max_sum with the best possible value
            if i + 1 % k == 0:
                if current_sum in prefix_sums:
                    max_sum = max(max_sum, current_sum - prefix_sums[0])
                else:
                    max_sum = max(max_sum, current_sum)

        return max_sum if max_sum != float('-inf') else 0

