    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        max_len = 0

        # Directions: (dx, dy)
        directions = [(1, 1), (-1, 1), (1, -1), (-1, -1)]

        # Check each cell as a possible starting point
        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue

                # Try each of the four diagonal directions
                for dx, dy in directions:
                    # First part of the V-shape
                    current = grid[i][j]
                    length = 1
                    x, y = i + dx, j + dy

                    # Traverse in this direction
                    while 0 <= x < n and 0 <= y < m:
                        if grid[x][y] == 2:
                            length += 1
                            x += dx
                            y += dy
                        elif grid[x][y] == 0:
                            length += 1
                            x += dx
                            y += dy
                        else:
                            break

                    # Now check for the turn
                    # We'll try to turn in the next direction
                    for next_dx, next_dy in directions:
                        if (dx, dy) == (next_dx, next_dy):
                            continue
                        x, y = i + next_dx, j + next_dy
                        if 0 <= x < n and 0 <= y < m:
