from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0

        # Helper function to calculate required operations for a subarray
        def get_ops(start, end):
            ops = 0
            prev = nums[start]
            for i in range(start + 1, end + 1):
                if nums[i] < prev:
                    ops += prev - nums[i]
                    prev = nums[i]
                else:
                    prev = nums[i]
            return ops

        # Iterate through all possible subarrays
        for i in range(n):
            for j in range(i, n):
                ops_needed = get_ops(i, j)
                if ops_needed <= k:
                    total += 1

        return total

def verify_solution():
    sol = Solution()
    print(sol.countNonDecreasingSubarrays([6,3,1,2,4,4], 7))  # Expected: 17
    print(sol.countNonDecreasingSubarrays([6,3,1,3,6], 4))   # Expected: 12

