class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        # Helper function to check if pattern is a subsequence of source
        def is_subsequence(s: str, t: str) -> bool:
            i = 0  # index for s
            j = 0  # index for t
            while i < len(s) and j < len(t):
                if s[i] == t[j]:
                    j += 1
                i += 1
            return j == len(t)

        # We can sort targetIndices to try removing from left to right
        targetIndices.sort()  # although input is already sorted, for consistency

        # We try removing characters in order and check if pattern is still a subsequence
        # We will use a greedy approach
        max_ops = 0
        for idx in targetIndices:
            # Create a new source string without idx
            new_source = source[:idx] + source[idx+1:]
            if is_subsequence(new_source, pattern):
                max_ops += 1
            else:
                break  # can't remove any more
        return max_ops

def evaluate_function():
    sol = Solution()
