from typing import List

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        # Count the frequency of each number
        freq = {}
        for num in nums:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1

        # Get the list of unique numbers
        unique_nums = sorted(freq.keys(), reverse=True)

        # If all numbers are same, then the outlier is the same as others
        if len(unique_nums) == 1:
            return unique_nums[0]

        # Try each number as the outlier
        for candidate in unique_nums:
            # Assume the candidate is the outlier
            # Then sum of the rest is the sum of all numbers except this one
            total_sum = sum(nums)
            sum_without_candidate = total_sum - candidate

            # Check if the sum_without_candidate exists in the list
            if sum_without_candidate in freq:
                return candidate

        # According to the problem statement, there is always an outlier, so this should not be reached
        return max(nums)

